def __getattr__(name: str):
    if name == "__version__":
        warnings.warn(
            "__version__ is deprecated and will be removed in a future version. Use importlib.metadata.version('marshmallow') instead.",
            DeprecationWarning,
            stacklevel=2,
        )
        return importlib.metadata.version("marshmallow")
    if name == "__version_info__":
        warnings.warn(
            "__version_info__ is deprecated and will be removed in a future version.",
            DeprecationWarning,
            stacklevel=2,
        )
        from packaging.version import Version
        version = importlib.metadata.version("marshmallow")
        parsed_version = Version(version)
        version_info: tuple[int, int, int] | tuple[
            int, int, int, str, int
        ] = parsed_version.release
        if parsed_version.pre:
            version_info += parsed_version.pre
        return version_info
    if name == "__parsed_version__":
        warnings.warn(
            "__parsed_version__ is deprecated and will be removed in a future version.",
            DeprecationWarning,
            stacklevel=2,
        )
        from packaging.version import Version
        return Version(importlib.metadata.version("marshmallow"))
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")

def __dir__():
    return sorted(list(globals().keys()) + ["__version__", "__version_info__", "__parsed_version__"])

